// Kalimat biasa: "Tanyakan tahun lahir, lalu kurangkan dari 2026
//                 untuk mendapatkan umur, lalu sebutkan umurnya."
DECLARE tahunLahir, umur : INTEGER
INPUT tahunLahir
umur ← 2026 - tahunLahir
OUTPUT "Umurmu tahun ini: ", umur

