// ALGORITMA HitungPendapatanDriver
// Input : tarif perjalanan (rupiah)
// Output: komisi aplikasi dan pendapatan bersih driver
DECLARE tarif, komisi, bersih : INTEGER
INPUT tarif
komisi ← tarif * 20 / 100
bersih ← tarif - komisi
OUTPUT "Komisi aplikasi: Rp", komisi
OUTPUT "Diterima driver: Rp", bersih

