// Masalah : hitung tarif ojek
// Input   : jarak (km)   Output: tarif (rupiah)
// Rumus   : tarif = 10000 + jarak * 2500
DECLARE jarak, tarif : INTEGER
INPUT jarak
tarif ← 10000 + jarak * 2500
OUTPUT "Tarif: Rp", tarif
